    public function isfromEvento($attribute){
	    if ($this->hasErrors($attribute)) return;
        $certificado=Subevento::model()->findByPk($this->id_subevento);
        if ($certificado->id_evento!=$this->id_evento){
            $this->addError($attribute,'Este Certificado não pertence ao Evento Selecionado');
        }
    }

    public function getLancado(){
	    if (!$this->id)
	        return false;
        $criteria = Yii::app()->db->createCommand();
        $presencas=$criteria->select ('id')
            ->from ('inscricaoatividade as t')
            ->where('id_atividade='.$this->id.' and presenca=true')
            ->queryall();
        if(count($presencas) == 0 )
            return false;
        return true;
    }

