	public function search() {
		$criteria = new CDbCriteria;


        if ( $this->tema) {
            $criteria->addCondition("unaccent_string(t.tema) ilike unaccent_string('%'||:param1||'%')");
            $criteria->params=[':param1'=>$this->tema];
        }
		$criteria->compare('qtdhoras', $this->qtdhoras);
		$criteria->compare('vagasdisponiveis', $this->vagasdisponiveis);
		$criteria->compare('multihorario', $this->multihorario);
		$criteria->compare('id_subevento', $this->id_subevento);
		$criteria->compare('presenca', $this->presenca);
		$criteria->compare('eletivo', $this->eletivo);
		$criteria->compare('id_evento', $this->id_evento);
		//$criteria->compare('id', $this->id);
		$criteria->compare('data', $this->data, true);
		$criteria->compare('horainicial', $this->horainicial, true);
		$criteria->compare('Proponente', $this->Proponente, true);
		$criteria->compare('horafinal', $this->horafinal, true);
        $criteria->compare('qtdeinscritos', $this->qtdeinscritos);
        $criteria->compare('local', $this->local, true);

        if ( $this->id==1 ) {
            $criteria->addCondition("id not in (select distinct id_atividade from inscricaoatividade where presenca=true)");
        }

        if ( $this->id==2 ) {
            $criteria->addCondition("id in (select distinct id_atividade from inscricaoatividade where presenca=true)");
        }



		return new CActiveDataProvider($this, array(
			'criteria' => $criteria,
		));
	}
